1	import type { CollisionShape3D, IPhysicsBodyHandle, IPhysicsContext } from "@threenative/physics";
2	import type { Vector3 } from "three";
3	
4	export type SpacePoint = Pick<Vector3, "x" | "y" | "z">;
5	
6	export interface IRayHit {
7	  readonly body: IPhysicsBodyHandle;
8	  readonly distance: number;
9	  readonly entity?: string;
10	  readonly normal: SpacePoint;
11	  readonly position: SpacePoint;
12	}
13	
14	export interface IShapeHit {
15	  readonly body: IPhysicsBodyHandle;
16	  readonly entity?: string;
17	  readonly position?: SpacePoint;
18	}
19	
20	export interface IPhysicsDirectSpaceState {
21	  intersectRay(options: {
22	    readonly collisionMask?: number;
23	    readonly from: SpacePoint;
24	    readonly maxResults?: number;
25	    readonly to: SpacePoint;
26	  }): IRayHit | undefined;
27	  intersectShape(options: {
28	    readonly collisionMask?: number;
29	    readonly maxResults?: number;
30	    readonly position: SpacePoint;
31	    readonly shape: CollisionShape3D;
32	  }): readonly IShapeHit[];
33	}
34	
35	type QueryPhysics = IPhysicsContext & {
36	  readonly directSpaceState: IPhysicsDirectSpaceState;
37	};
